WITH scored AS (SELECT *, AVG(salary) OVER w_hist AS salary_avg_5_prior, LAST_VALUE(job_title, TRUE) OVER (PARTITION BY level ORDER BY hire_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_job_title FROM employees WINDOW w_hist AS (PARTITION BY level ORDER BY hire_date, id ROWS BETWEEN 5 PRECEDING AND 1 PRECEDING)) SELECT dept_id, level, APPROX_PERCENTILE(salary_avg_5_prior, ARRAY(0.25, 0.5, 0.75)) AS salary_avg_5_prior_quartiles, APPROX_PERCENTILE(salary, 0.9) AS salary_p90, ROUND(AVG(salary), 2) AS avg_salary, GROUPING_ID() AS grouping_id FROM scored GROUP BY ROLLUP (dept_id, level) HAVING salary_p90 >= 0 ORDER BY dept_id DESC;
